package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.service.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
class JdbcPricePoliciesTest extends JdbcCouponInventoryTest {
 PricePolicies policies;MerchantQuotes quotes;
 @BeforeEach void price(TestInfo info){jdbc.execute("DROP TRIGGER IF EXISTS fail_price_audit");jdbc.update("DELETE FROM price_monitor_policy");jdbc.update("DELETE FROM merchant_project_version");jdbc.update("UPDATE operator_account SET can_price_monitor=1 WHERE id=1");jdbc.update("UPDATE standard_project SET source_note='synthetic licensed source',service_content='synthetic service',revision=1");var manager=new DataSourceTransactionManager(jdbc.getDataSource());policies=new PricePolicies(db,new OperatorIdentity(jdbc,null,manager));quotes=new MerchantQuotes(jdbc,db.writes,json,new ServiceCatalog(jdbc,manager),manager);if(info.getTestMethod().orElseThrow().getDeclaringClass()!=JdbcCouponInventoryTest.class){jdbc.update("UPDATE merchant_project SET on_shelf=0 WHERE id<>1");saveQuote();}clock.value=Instant.now().plusSeconds(60).truncatedTo(java.time.temporal.ChronoUnit.SECONDS);}
 @AfterEach void cleanPrice(){jdbc.execute("DROP TRIGGER IF EXISTS fail_price_audit");}
 void saveQuote(){quotes.save(merchant,key(),new QuoteInput(1,new BigDecimal("12.34"),1));}
 com.fasterxml.jackson.databind.JsonNode sources(){return json.valueToTree(policies.quotes(operator,1));}
 String hash(){for(var n:sources().path("items"))if(n.path("quote_id").asLong()==1)return n.path("source_hash").asText();throw new AssertionError();}
 ObjectNode config(){return json.createObjectNode().put("quote_id",1).put("source_hash",hash()).put("lower_price","10.00").put("upper_price","15.00").put("price_unit","次").put("applicability_note","仅适用所选版本明确服务内容").put("source_note","synthetic confirmed price source").put("scope_confirmed",true).put("valid_from",clock.value.plusSeconds(3600).toString()).put("valid_to",clock.value.plusSeconds(7200).toString());}
 long policy(){var b=config();PricePolicyInput.body(b.toString(),false);return policies.create(operator,key(),b).path("data").path("id").asLong();}
 void activate(long id){policies.status(operator,id,key(),statusBody(1,"PUBLISHED"));}
 @Test void realQuoteVersionAndAuditAreRequiredAndUnknownLegacyCannotConfirm(){var n=sources();assertEquals(1,n.path("items").size());assertEquals("READY",n.path("items").get(0).path("state").asText());jdbc.update("UPDATE merchant_project_version SET actor_staff_id=NULL");assertEquals("UNKNOWN",sources().path("items").get(0).path("state").asText());assertEquals(409,code(()->policies.create(operator,key(),config().put("source_hash","a".repeat(64)))));assertEquals(0,count("price_monitor_policy"));}
 @Test void independentPermissionAndReplayAlwaysReauthorize(){jdbc.update("UPDATE operator_account SET can_price_monitor=0,can_catalog=1,can_analytics=1,can_assessment=1 WHERE id=1");assertEquals(403,code(()->policies.quotes(operator,1)));assertEquals(403,code(()->policies.list(operator,1)));jdbc.update("UPDATE operator_account SET can_price_monitor=1 WHERE id=1");var b=config();String k=key();policies.create(operator,k,b);jdbc.update("UPDATE operator_account SET can_price_monitor=0 WHERE id=1");assertEquals(403,code(()->policies.create(operator,k,b)));}
 @Test void snapshotCasFreezeAndOnePublishedPerQuote(){long p=policy();var b=config().put("expected_revision",1).put("lower_price","9.00");policies.update(operator,p,key(),b);assertEquals(409,code(()->policies.update(operator,p,key(),b)));policies.status(operator,p,key(),statusBody(2,"PUBLISHED"));assertEquals(409,code(()->policies.update(operator,p,key(),b.put("expected_revision",3))));long replacement=policy();assertEquals(409,code(()->activate(replacement)));policies.status(operator,p,key(),statusBody(3,"STOPPED"));activate(replacement);assertEquals(409,code(()->policies.status(operator,p,key(),statusBody(4,"PUBLISHED"))));var v=policies.detail(operator,p);assertEquals(true,v.get("comparison_available"));assertFalse(db.json(v).contains("submission_key"));}
 @Test void priceVersionProjectContentAndProofChangesInvalidateDraftPublication(){long p=policy();saveQuote();assertEquals(409,code(()->activate(p)));long next=policy();jdbc.update("UPDATE standard_project SET service_content='changed service' WHERE id=1");assertEquals(409,code(()->activate(next)));var b=config();jdbc.update("DELETE FROM audit_log WHERE action='MERCHANT_PROJECT_SAVE'");assertEquals("UNKNOWN",sources().path("items").get(0).path("state").asText());assertEquals(409,code(()->policies.create(operator,key(),b)));}
 @Test void sourcePriceOrAuditTamperingAndMissingProjectSourceStayUnknown(){jdbc.update("UPDATE merchant_project SET price=99 WHERE id=1");assertEquals("UNKNOWN",sources().path("items").get(0).path("state").asText());jdbc.update("UPDATE merchant_project SET price=12.34 WHERE id=1");jdbc.update("UPDATE audit_log SET after_state=JSON_SET(after_state,'$.price','99.00') WHERE action='MERCHANT_PROJECT_SAVE'");assertEquals("UNKNOWN",sources().path("items").get(0).path("state").asText());saveQuote();jdbc.update("UPDATE standard_project SET source_note='' WHERE id=1");assertEquals("UNKNOWN",sources().path("items").get(0).path("state").asText());}
 @Test void sourceCanDisappearButExistingPublishedPolicyCanAlwaysStop(){long p=policy();activate(p);jdbc.update("UPDATE merchant SET status=0 WHERE id=1");policies.status(operator,p,key(),statusBody(2,"STOPPED"));assertEquals("STOPPED",policies.row(p,false).get("status"));assertEquals(0L,policies.quotes(operator,1).get("total"));assertNotNull(policies.detail(operator,p).get("source_snapshot"));}
 @Test void permanentCreationReceiptSurvivesSourceAndWindowAfterGenericExpiry(){String k=key();var b=config();var first=policies.create(operator,k,b);long p=first.path("data").path("id").asLong();activate(p);clock.value=clock.value.plusSeconds(10000);jdbc.update("UPDATE merchant SET status=0 WHERE id=1");jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY)");assertEquals(first.path("data"),policies.create(operator,k,b).path("data"));assertEquals(1,count("price_monitor_policy"));jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY)");assertEquals(400,code(()->policies.create(operator,k,b.deepCopy().put("upper_price","16.00"))));}
 @Test void futureWindowRecheckedAtSaveAndPublish(){var b=config().put("valid_from",clock.value.toString());assertEquals(409,code(()->policies.create(operator,key(),b)));long p=policy();clock.value=clock.value.plusSeconds(3600);assertEquals(409,code(()->activate(p)));assertEquals("DRAFT",policies.row(p,false).get("status"));}
 @Test void auditFailureRollsBackDraftAndPublication(){var b=config();jdbc.execute("CREATE TRIGGER fail_price_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->policies.create(operator,key(),b)));assertEquals(0,count("price_monitor_policy"));jdbc.execute("DROP TRIGGER fail_price_audit");long p=policy();jdbc.execute("CREATE TRIGGER fail_price_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->activate(p)));assertEquals("DRAFT",policies.row(p,false).get("status"));}
 @Test void differentOperatorsCannotPublishTwoRangesForOneQuote()throws Exception{long a=policy(),b=policy();jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_price_monitor) VALUES(2,'price-peer','unused','13800000001',1)");var second=new OperatorActor(2,session(2,"operator_account","OPERATOR",OperatorActor.APP,null),Instant.now().plusSeconds(600));var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var one=pool.submit(()->{start.await();try{activate(a);return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});var two=pool.submit(()->{start.await();try{policies.status(second,b,key(),statusBody(1,"PUBLISHED"));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});start.countDown();var codes=new ArrayList<>(List.of(one.get(30,TimeUnit.SECONDS),two.get(30,TimeUnit.SECONDS)));Collections.sort(codes);assertEquals(List.of(200,409),codes);}finally{pool.shutdownNow();}}
 @Test void exactRangeConfirmationAndTextAreValidatedWithoutInferringThresholds(){var b=config();for(var invalid:List.of(b.deepCopy().put("scope_confirmed",false),b.deepCopy().put("lower_price","0.00"),b.deepCopy().put("lower_price","16.00"),b.deepCopy().put("upper_price",15),b.deepCopy().put("price_unit"," 次 "),b.deepCopy().put("source_note",""),b.deepCopy().put("valid_to",b.path("valid_from").asText()),b.deepCopy().put("price",12)))assertThrows(Exception.class,()->PricePolicyInput.body(invalid.toString(),false));assertThrows(Exception.class,()->PricePolicyInput.body(b+"{}",false));PricePolicyInput.body(b.deepCopy().put("upper_price","10.00").toString(),false);assertEquals(400,code(()->policies.list(operator,0)));}
}
